// WORKFLOW 1: Incident Intake - Validate
const raw = $input.first().json;
const payload = raw.body || raw;
const incident = payload.incident || {};
const responsePlan = payload.responsePlan || {};
const resources = payload.resources || { ambulances: [], rescueTeams: [], drones: [] };
const action = payload.action || 'TRIGGER_FULL_ORCHESTRATION';

if (!incident.id || !incident.code) {
  throw new Error('Incident validation failed: id or code missing.');
}

const isCritical = incident.severity === 'CRITICAL' || incident.severity === 'HIGH';

return [{
  json: {
    incident,
    responsePlan,
    resources,
    action,
    simulationMode: payload.simulationMode !== undefined ? payload.simulationMode : true,
    intakeValidated: true,
    isCritical,
    intakeTimestamp: new Date().toISOString()
  }
}];

// W2: Allocate Resources & Trigger Mock Emergency Services
const data = $input.first().json;
const incident = data.incident;
const req = data.responsePlan?.resourceAllocation || { ambulances: 2, rescueTeams: 2, drones: 1 };

const allocated = {
  incidentId: incident.id,
  ambulances: req.ambulances || 2,
  rescueTeams: req.rescueTeams || 2,
  drones: req.drones || 1,
  priorityZone: incident.primaryLocation?.name || 'Zone A',
  approvedAt: new Date().toISOString()
};

return [{
  json: {
    ...data,
    allocated,
    criticalResponseApproved: true
  }
}];

// W3: Drone Deployment Logic
const data = $input.first().json;
const targetZone = data.incident?.primaryLocation?.name || 'Zone A';

const isDeployAction = data.action === 'DEPLOY_DRONE' || data.criticalResponseApproved;

const droneStatus = isDeployAction ? 'IN_FLIGHT' : 'READY';
const droneMission = {
  missionId: `MSN-DRONE-${Date.now().toString(36).toUpperCase()}`,
  droneCallsign: 'UAV Echo-1',
  model: 'Matrice 300 RTK',
  targetZone,
  flightStatus: droneStatus,
  altitudeMeters: 45,
  payload: 'Thermal FLIR + Floatation Vest Drop',
  timestamp: new Date().toISOString()
};

return [{
  json: {
    ...data,
    droneMission,
    droneWorkflowStatus: droneStatus
  }
}];

// W4: Emergency Alert Logic & Response Formatter
const data = $input.first().json;
const isAlertApproved = data.action === 'APPROVE_EMERGENCY_ALERT';
const emergencyAlertStatus = isAlertApproved ? 'SIMULATED' : 'PENDING APPROVAL';
const alertPayload = {
  alertId: `CAP-${data.incident?.code || 'ALERT'}`,
  headline: `URGENT FLOOD EVACUATION: ${data.incident?.primaryLocation?.name || 'Zone A'}`,
  status: emergencyAlertStatus,
  channel: 'SIMULATED_CELL_BROADCAST'
};

const criticalStatus = data.criticalResponseApproved ? 'APPROVED' : 'WAITING FOR APPROVAL';
const droneStatus = data.droneWorkflowStatus || 'READY';

const response = {
  success: true,
  orchestrator: 'RUNNING',
  incidentIntake: 'COMPLETED',
  criticalResponse: criticalStatus,
  droneWorkflow: droneStatus,
  emergencyAlert: emergencyAlertStatus,
  allocated: data.allocated || null,
  droneMission: data.droneMission || null,
  alertPayload,
  logs: [
    {
      id: 'log-master-1',
      timestamp: new Date().toISOString(),
      workflow: 'Incident Intake',
      status: 'SUCCESS',
      message: 'Incident intake validated and categorized: ' + (data.incident?.code || 'ACTIVE')
    },
    {
      id: 'log-master-2',
      timestamp: new Date().toISOString(),
      workflow: 'Critical Response',
      status: data.criticalResponseApproved ? 'SUCCESS' : 'PENDING',
      message: data.criticalResponseApproved ? 'Human approval verified. Dispatch orders queued to mock CAD.' : 'Human authorization safeguard armed. Awaiting commander sign-off.'
    },
    {
      id: 'log-master-3',
      timestamp: new Date().toISOString(),
      workflow: 'Drone Deployment',
      status: 'SUCCESS',
      message: 'UAV Echo-1 status: ' + droneStatus
    },
    {
      id: 'log-master-4',
      timestamp: new Date().toISOString(),
      workflow: 'Emergency Alert',
      status: emergencyAlertStatus === 'SIMULATED' ? 'MOCK' : 'PENDING',
      message: 'Emergency broadcast status: ' + emergencyAlertStatus
    }
  ],
  disclaimer: 'PROTOTYPE DEMONSTRATION: External real emergency services are not connected. Dispatch actions are simulated via mock stubs.'
};

return [{ json: response }];
